import base64,html,json,pathlib,shutil,subprocess
R=pathlib.Path(__file__).resolve().parents[1];O=R/'.local-server/music-board';O.mkdir(parents=True,exist_ok=True)
FFMPEG=shutil.which('ffmpeg');assert FFMPEG,'FFmpeg is required to build audition MP3s'
tracks=json.loads((R/'public/audio-v5/manifest.json').read_text(encoding='utf-8'));sections=[]
for t in tracks:
 country=t['country'];ident='spain' if country=='Spain' else 'argentina';target=O/(ident+'-toy-pop.mp3')
 subprocess.run([FFMPEG,'-hide_banner','-loglevel','error','-y','-i',str(R/'public/audio-v5'/t['file']),'-codec:a','libmp3lame','-b:a','128k','-ar','24000',str(target)],check=True,creationflags=subprocess.CREATE_NO_WINDOW)
 uri='data:audio/mpeg;base64,'+base64.b64encode(target.read_bytes()).decode('ascii')
 sections.append(f'''<section class="track {ident}" aria-labelledby="title-{ident}"><div class="track-heading"><span class="flag" aria-hidden="true"></span><div><h2 id="title-{ident}">{html.escape(country)}</h2><p class="song">{html.escape(t['title'].split(' · ')[0])}</p></div><button type="button" class="play" data-track="{ident}">Play {country}</button></div><p class="description">{'The royal march with a bouncing bass line and bright toy-style melody.' if ident=='spain' else 'The anthem’s chorus with a playful lead, music-box accents and a pop beat.'}</p><audio id="{ident}" controls preload="metadata" aria-label="{country} toy-pop winning song" src="{uri}"></audio><p class="meta">120 BPM · 32 seconds · Instrumental draft</p></section>''')
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sloppy Soccer · Victory sound board</title><style>
.board{box-sizing:border-box;width:min(720px,calc(100vw - 20px));padding:16px;color:var(--foreground,#25394a)}h1{font-size:1.6rem;line-height:1.2;margin:0 0 8px}h2{font-size:1.2rem;margin:0 0 3px}.intro{color:var(--muted-foreground,#5e6d79);max-width:62ch;line-height:1.5;margin:0 0 16px}.track{padding:20px 0;border-top:1px solid var(--border,#b7c4ce)}.track-heading{display:flex;align-items:center;gap:12px}.track-heading>div{flex:1;min-width:0}.song{font-size:.95rem;margin:0;line-height:1.4}.flag{display:block;flex:0 0 33px;height:24px;border:1px solid #707b84}.spain .flag{background:linear-gradient(#bd2135 0 25%,#f7cc45 25% 75%,#bd2135 75%)}.argentina .flag{background:linear-gradient(#71b7e3 0 33.3%,#fff 33.3% 66.6%,#71b7e3 66.6%)}button{font:inherit;cursor:pointer;color:var(--foreground,#25394a);border:1px solid var(--border,#a8b6c3);background:var(--card,#eef2f6);padding:10px 14px;border-radius:7px}button:hover{border-color:var(--accent,#345fb4)}button:focus-visible,input:focus-visible,a:focus-visible{outline:3px solid var(--accent,#345fb4);outline-offset:3px}.play{font-weight:650;min-width:126px}.play[aria-pressed=true]{box-shadow:inset 0 -3px var(--accent,#345fb4)}.description{margin:12px 0;color:var(--muted-foreground,#5e6d79);line-height:1.45;font-size:.93rem}audio{display:block;width:100%;height:42px}.meta{margin:7px 0 0;font-size:.82rem;color:var(--muted-foreground,#5e6d79)}.controls{display:flex;flex-wrap:wrap;gap:16px;align-items:center;padding-top:16px;border-top:1px solid var(--border,#b7c4ce)}.volume{display:flex;align-items:center;gap:8px}.volume input{width:100px;accent-color:var(--accent,#345fb4)}.loop{display:flex;align-items:center;gap:6px}.status{font-size:.9rem;min-height:1.3em}.note{font-size:.85rem;line-height:1.5;color:var(--muted-foreground,#5e6d79)}details{font-size:.85rem}details p{line-height:1.5}a{color:var(--accent,#345fb4)}@media(max-width:440px){.board{padding:10px}.track-heading{gap:8px}.play{min-width:108px;padding:10px}.song{font-size:.86rem}.controls{gap:12px}.flag{flex-basis:25px;height:20px}}
</style></head><body><main class="board"><h1>Victory sound board</h1><p class="intro">Two anthem-based toy-pop drafts for Sloppy Soccer. Press Play to listen. Starting one track stops the other.</p>SECTIONS<div class="controls"><button type="button" id="stop">Stop all</button><label class="volume">Volume <input id="volume" type="range" min="0" max="100" step="5" value="65"><output id="level">65%</output></label><label class="loop"><input id="loop" type="checkbox">Loop playback</label></div><p id="status" class="status" role="status" aria-live="polite">Ready to listen</p><p class="note">Approved for Spain and Argentina victories. The game selects the winning team’s track; draws remain neutral. These are new instrumental arrangements, not official anthem recordings.</p><details><summary>Melody sources</summary><p>Spain: the historic Marcha Real melody, checked against <a href="https://www.joseane.com/polifonicas/marcha-real/" target="_blank" rel="noopener">JoseanE’s freely released 1761-melody arrangement</a>. Argentina: the vocal chorus line from the <a href="https://earme.cancilleria.gob.ar/es/content/himno-nacional-argentino" target="_blank" rel="noopener">Argentinian embassy’s anthem score/MIDI reference</a>. Only the melody is used; all accompaniment and audio synthesis are new.</p></details></main><script>
const tracks=[...document.querySelectorAll('audio')];const status=document.querySelector('#status');const buttons=[...document.querySelectorAll('[data-track]')];const names={spain:'Spain',argentina:'Argentina'};function sync(){for(const b of buttons){const a=document.getElementById(b.dataset.track),playing=!a.paused;b.textContent=(playing?'Pause ':'Play ')+names[a.id];b.setAttribute('aria-pressed',String(playing));}const active=tracks.find(a=>!a.paused);status.textContent=active?'Playing '+names[active.id]:tracks.some(a=>a.currentTime>0)?'Paused':'Stopped';}for(const a of tracks){a.volume=.65;a.addEventListener('play',()=>{for(const other of tracks)if(other!==a){other.pause();other.currentTime=0;}sync();});for(const event of ['pause','ended','seeked'])a.addEventListener(event,sync);a.addEventListener('error',()=>{status.textContent='This track could not be decoded by your browser. Try downloading the MP3.';});}for(const b of buttons)b.addEventListener('click',async()=>{const a=document.getElementById(b.dataset.track);try{if(a.paused)await a.play();else a.pause();sync();}catch(e){status.textContent='Playback could not start. Try the audio player’s Play button.';}});document.querySelector('#stop').addEventListener('click',()=>{for(const a of tracks){a.pause();a.currentTime=0;}sync();});document.querySelector('#volume').addEventListener('input',e=>{for(const a of tracks)a.volume=Number(e.target.value)/100;document.querySelector('#level').textContent=e.target.value+'%';});document.querySelector('#loop').addEventListener('change',e=>{for(const a of tracks)a.loop=e.target.checked;});window.addEventListener('pagehide',()=>tracks.forEach(a=>a.pause()));
</script></body></html>'''.replace('SECTIONS',''.join(sections))
(O/'sound-board.html').write_text(page,encoding='utf-8');print('BOARD',str(O/'sound-board.html'),'bytes',len(page.encode('utf-8')))
